    messages = [
      { ...messages[0]!, id: MessageId.make("older-user"), createdAt: "2026-09-03T23:59:00.000Z" },
      ...messages,
    ];
    check();
    messages = messages.map((message) =>
      message.id === MessageId.make("live-assistant")
        ? { ...message, role: "user", turnId: null, createdAt: initial.time(0) }
