describe("handleSessionSearchKeyDown", () => {
  function event(
    key: string,
    overrides: Partial<{
      readonly shiftKey: boolean;
      readonly keyCode: number;
      readonly isComposing: boolean;
    }> = {},
  ) {
    return {
      key,
      shiftKey: overrides.shiftKey ?? false,
      keyCode: overrides.keyCode ?? 0,
      nativeEvent: { isComposing: overrides.isComposing ?? false },
      preventDefault: vi.fn(),
      stopPropagation: vi.fn(),
    };
  }

  it("routes Enter, Shift+Enter, and Escape after preventing browser handling", () => {
    const actions = {
      close: vi.fn(),
      next: vi.fn(),
      previous: vi.fn(),
    };
    const nextEvent = event("Enter");
    const previousEvent = event("Enter", { shiftKey: true });
    const closeEvent = event("Escape");

    expect(handleSessionSearchKeyDown(nextEvent, actions)).toBe(true);
    expect(handleSessionSearchKeyDown(previousEvent, actions)).toBe(true);
    expect(handleSessionSearchKeyDown(closeEvent, actions)).toBe(true);
    expect(actions.next).toHaveBeenCalledOnce();
    expect(actions.previous).toHaveBeenCalledOnce();
    expect(actions.close).toHaveBeenCalledOnce();
    for (const handledEvent of [nextEvent, previousEvent, closeEvent]) {
      expect(handledEvent.preventDefault).toHaveBeenCalledOnce();
      expect(handledEvent.stopPropagation).toHaveBeenCalledOnce();
    }
  });

  it.each([
    ["Enter", { isComposing: true }],
    ["Escape", { isComposing: true }],
    ["Enter", { keyCode: 229 }],
    ["Escape", { keyCode: 229 }],
  ] as const)("ignores %s during IME composition", (key, overrides) => {
    const composingEvent = event(key, overrides);
    const actions = {
      close: vi.fn(),
      next: vi.fn(),
      previous: vi.fn(),
    };

    expect(handleSessionSearchKeyDown(composingEvent, actions)).toBe(false);
    expect(composingEvent.preventDefault).not.toHaveBeenCalled();
    expect(composingEvent.stopPropagation).not.toHaveBeenCalled();
    expect(actions.close).not.toHaveBeenCalled();
    expect(actions.next).not.toHaveBeenCalled();
    expect(actions.previous).not.toHaveBeenCalled();
  });
});

import type { TimelineEntry } from "../../session-logic";
import {
  deriveSearchableTimelineRows,
  type TimelineLatestTurn,
  workEntryDisplayLabel,
} from "./MessagesTimeline.logic";

export const SESSION_SEARCH_MAX_QUERY_LENGTH = 200;

export type SessionSearchMatchKind = "user" | "assistant" | "proposed-plan" | "activity";

export interface SessionSearchMatch {
  readonly key: string;
  readonly entryId: string;
  readonly kind: SessionSearchMatchKind;
  readonly occurrence: number;
  readonly normalizedIndex: number;
}

export interface SessionSearchState {
  readonly open: boolean;
  readonly query: string;
  readonly activeMatchKey: string | null;
  readonly focusRequestId: number;
}

export type SessionSearchAction =
  | { readonly type: "open" }
  | { readonly type: "close" }
  | { readonly type: "thread-changed" }
  | { readonly type: "query-changed"; readonly query: string }
  | { readonly type: "select-match"; readonly matchKey: string };

export const INITIAL_SESSION_SEARCH_STATE: SessionSearchState = {
  open: false,
  query: "",
  activeMatchKey: null,
  focusRequestId: 0,
};

export function reduceSessionSearchState(
  state: SessionSearchState,
  action: SessionSearchAction,
): SessionSearchState {
  switch (action.type) {
    case "open":
      return {
        ...state,
        open: true,
        focusRequestId: state.focusRequestId + 1,
      };
    case "query-changed":
      return {
        ...state,
        query: action.query.slice(0, SESSION_SEARCH_MAX_QUERY_LENGTH),
        activeMatchKey: null,
      };
    case "select-match":
      return {
        ...state,
        activeMatchKey: action.matchKey,
      };
    case "close":
    case "thread-changed":
      return {
        ...INITIAL_SESSION_SEARCH_STATE,
        focusRequestId: state.focusRequestId,
      };
  }
}

export interface SessionSearchKeyboardEvent {
  readonly key: string;
  readonly shiftKey: boolean;
  readonly keyCode: number;
  readonly nativeEvent: {
    readonly isComposing: boolean;
  };
  readonly preventDefault: () => void;
  readonly stopPropagation: () => void;
}

export function handleSessionSearchKeyDown(
  event: SessionSearchKeyboardEvent,
  actions: {
    readonly close: () => void;
    readonly next: () => void;
    readonly previous: () => void;
  },
): boolean {
  if (event.nativeEvent.isComposing || event.keyCode === 229) {
    return false;
  }

  const action =
    event.key === "Escape"
      ? actions.close
      : event.key === "Enter"
        ? event.shiftKey
          ? actions.previous
          : actions.next
        : null;
  if (action === null) {
    return false;
  }

  event.preventDefault();
  event.stopPropagation();
  action();
  return true;
}

export function normalizeSessionSearchText(value: string): string {
  return value.normalize("NFKC").toLowerCase();
}

export interface SessionSearchTimelineContext {
  readonly isWorking?: boolean;
  readonly latestTurn?: TimelineLatestTurn | null;
  readonly runningTurnId?: TimelineLatestTurn["turnId"] | null;
  readonly workspaceRoot?: string | undefined;
  readonly liveAgentTaskIds?: ReadonlySet<string> | undefined;
}

function searchableWorkEntryIds(
  entries: ReadonlyArray<TimelineEntry>,
  options: SessionSearchTimelineContext | undefined,
): ReadonlySet<string> {
  const rows = deriveSearchableTimelineRows({
    timelineEntries: entries,
    isWorking: options?.isWorking ?? false,
    latestTurn: options?.latestTurn ?? null,
    runningTurnId: options?.runningTurnId ?? null,
    liveAgentTaskIds: options?.liveAgentTaskIds,
    activeTurnStartedAt: null,
    turnDiffSummaries: [],
    supportsConversationRollback: false,
  });
  return new Set(
    rows.flatMap((row) =>
      row.kind === "work"
        ? row.groupedEntries
            .filter((entry) => entry.agentSpawn === undefined)
            .map((entry) => entry.id)
        : [],
    ),
  );
}

function searchableEntryText(
  entry: TimelineEntry,
  searchableWorkIds: ReadonlySet<string>,
  workspaceRoot: string | undefined,
): { readonly kind: SessionSearchMatchKind; readonly text: string } | null {
  switch (entry.kind) {
    case "message":
      if (entry.message.role !== "user" && entry.message.role !== "assistant") {
        return null;
      }
      return { kind: entry.message.role, text: entry.message.text };
    case "proposed-plan":
      return { kind: "proposed-plan", text: entry.proposedPlan.planMarkdown };
    case "work":
      return searchableWorkIds.has(entry.id)
        ? {
            kind: "activity",
            text: workEntryDisplayLabel(entry.entry, workspaceRoot),
          }
        : null;
  }
}

export function deriveSessionSearchMatches(
  entries: ReadonlyArray<TimelineEntry>,
  rawQuery: string,
  options?: SessionSearchTimelineContext,
): SessionSearchMatch[] {
  const query = normalizeSessionSearchText(rawQuery.trim());
  if (query.length === 0) {
    return [];
  }

  const searchableWorkIds = searchableWorkEntryIds(entries, options);
  const matches: SessionSearchMatch[] = [];
  for (const entry of entries) {
    const searchable = searchableEntryText(entry, searchableWorkIds, options?.workspaceRoot);
    if (searchable === null) {
      continue;
    }
    const text = normalizeSessionSearchText(searchable.text);
    let occurrence = 0;
    let searchFrom = 0;
    while (searchFrom <= text.length - query.length) {
      const index = text.indexOf(query, searchFrom);
      if (index < 0) {
        break;
      }
      matches.push({
        key: JSON.stringify([entry.id, searchable.kind, occurrence, index]),
        entryId: entry.id,
        kind: searchable.kind,
        occurrence,
        normalizedIndex: index,
      });
      occurrence += 1;
      searchFrom = index + query.length;
    }
  }
  return matches;
}

export function resolveSessionSearchMatchIndex(
  matches: ReadonlyArray<SessionSearchMatch>,
  activeMatchKey: string | null,
): number {
  if (matches.length === 0) {
    return -1;
  }
  if (activeMatchKey === null) {
    return 0;
  }
  const index = matches.findIndex((match) => match.key === activeMatchKey);
  return index < 0 ? 0 : index;
}

export function navigateSessionSearchMatch(
  matches: ReadonlyArray<SessionSearchMatch>,
  activeMatchKey: string | null,
  direction: "next" | "previous",
): SessionSearchMatch | null {
  const currentIndex = resolveSessionSearchMatchIndex(matches, activeMatchKey);
  if (currentIndex < 0) {
    return null;
  }
  const delta = direction === "next" ? 1 : -1;
  return matches[(currentIndex + delta + matches.length) % matches.length] ?? null;
}

import type { LegendListRef } from "@legendapp/list/react";
import type { TurnId } from "@t3tools/contracts";
import { useCallback, useEffect, useRef, useState, type RefObject } from "react";
import type { TimelineEntry } from "../../session-logic";
import type { MessagesTimelineRow } from "./MessagesTimeline.logic";
import type { AssistantCitationRequest, AssistantCitationTarget } from "./AssistantCitationSource";
import { toastManager } from "../ui/toast";

export interface CitationHistoryPage {
  readonly loading: boolean;
  readonly cursor?: string | null;
  readonly onLoadEarlier: () => void;
}

/** Fetch, unfold, and mount the source before its measured quote owns scrolling. */
export function useAssistantCitationTarget({
  request,
  entries,
  rows,
  listRef,
  viewport,
  historyLoading,
  loadEarlier,
  onExpandTurn,
  onManualNavigation,
}: {
  request: AssistantCitationRequest | null;
  entries: ReadonlyArray<TimelineEntry>;
  rows: ReadonlyArray<MessagesTimelineRow>;
  listRef: RefObject<LegendListRef | null>;
  viewport: HTMLElement | null;
  historyLoading: boolean;
  loadEarlier: CitationHistoryPage | null;
  onExpandTurn: (turnId: TurnId) => void;
  onManualNavigation: () => void;
}) {
  const [ready, setReady] = useState<AssistantCitationTarget | null>(null);
  const [finishedKey, setFinishedKey] = useState<string | null>(null);
  const [listLoaded, setListLoaded] = useState(false);
  const onListLoad = useCallback(() => setListLoaded(true), []);
  const navigationRef = useRef<{
    target: AssistantCitationTarget;
    requestedPages: Set<string>;
    done: boolean;
  } | null>(null);

  useEffect(() => {
    if (navigationRef.current && navigationRef.current.target.key !== request?.key) {
      navigationRef.current.target.activationRef.current.dismissed = true;
      navigationRef.current.target.activationRef.current.cancelScroll?.();
    }
    if (!request) {
      navigationRef.current = null;
      setReady(null);
      setFinishedKey(null);
      return;
    }
    if (navigationRef.current?.target.key !== request.key) {
      const target: AssistantCitationTarget = {
        ...request,
        activationRef: { current: { scrolled: false, dismissed: false } },
        onComplete: () => {
          if (navigationRef.current?.target !== target) return;
          navigationRef.current.done = true;
          // ChatView's thread-open effect can run after our initial opt-out.
          onManualNavigation();
          setFinishedKey(target.key);
        },
      };
      navigationRef.current = {
        target,
        requestedPages: new Set(),
        done: false,
      };
      setReady(null);
      onManualNavigation();
    }
    if (!viewport || historyLoading) return;
    const navigation = navigationRef.current;
    if (navigation.done || navigation.target.activationRef.current.dismissed) return;
    const fail = (title: string, description: string) => {
      navigation.done = true;
      setFinishedKey(navigation.target.key);
      toastManager.add({ type: "warning", title, description });
    };
    const source = entries.find(
      (entry) =>
        entry.kind === "message" && entry.message.id === navigation.target.citation.messageId,
    );
    if (!source) {
      if (loadEarlier) {
        if (loadEarlier.loading) return;
        const cursor = loadEarlier.cursor ?? entries[0]?.id ?? "first";
        if (navigation.requestedPages.has(cursor) || navigation.requestedPages.size >= 20) {
          fail(
            "Could not load the cited response",
            "Load earlier turns, then click the citation to try again. Your saved quote is unchanged.",
          );
          return;
        }
        navigation.requestedPages.add(cursor);
        loadEarlier.onLoadEarlier();
        return;
      }
      fail(
        "The cited response is unavailable",
        "It may have been removed. The selected text is still saved in your citation.",
      );
      return;
    }
    if (source.kind !== "message" || source.message.role !== "assistant") {
      fail(
        "The citation does not refer to an assistant response",
        "The selected text is still saved in your citation.",
      );
      return;
    }
    const index = rows.findIndex(
      (row) => row.kind === "message" && row.message.id === navigation.target.citation.messageId,
    );
    if (index < 0) {
      if (source.message.turnId) onExpandTurn(source.message.turnId);
      return;
    }
    if (listLoaded && listRef.current) setReady(navigation.target);
  }, [
    entries,
    historyLoading,
    listLoaded,
    listRef,
    loadEarlier,
    onExpandTurn,
    onManualNavigation,
    request,
    rows,
    viewport,
  ]);

  const dismiss = useCallback(
    (onlyPending = false) => {
      const navigation = navigationRef.current;
      if (!request || !navigation || navigation.target.key !== request.key) return;
      const activation = navigation.target.activationRef.current;
      if (activation.dismissed || (onlyPending && (activation.scrolled || navigation.done))) return;
      activation.dismissed = true;
      activation.cancelScroll?.();
      if (!activation.scrolled && !navigation.done) onManualNavigation();
      navigation.done = true;
      setReady(null);
      setFinishedKey(request.key);
    },
    [onManualNavigation, request],
  );

  useEffect(() => {
    if (!request) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        dismiss(false);
      } else if (
        viewport?.contains(event.target as Node) &&
        ["ArrowUp", "ArrowDown", "PageUp", "PageDown", "Home", "End", " "].includes(event.key)
      ) {
        dismiss(true);
      }
    };
    const onWheel = (event: WheelEvent) => {
      if (event.deltaY !== 0) dismiss(true);
    };
    const onNavigation = () => dismiss(true);
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onNavigation, true);
    viewport?.addEventListener("wheel", onWheel, { passive: true });
    viewport?.addEventListener("touchmove", onNavigation, { passive: true });
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onNavigation, true);
      viewport?.removeEventListener("wheel", onWheel);
      viewport?.removeEventListener("touchmove", onNavigation);
    };
  }, [dismiss, request, viewport]);

  const target = ready?.key === request?.key ? ready : null;
  const positioning = request !== null && finishedKey !== request.key;
  const sourceRow =
    target && positioning
      ? rows.find((row) => row.kind === "message" && row.message.id === target.citation.messageId)
      : undefined;
  return {
    target,
    positioning,
    onListLoad,
    dismiss,
    alwaysRender: sourceRow ? { keys: [sourceRow.id] } : undefined,
  };
}

