describe("composer and pull request shortcuts", () => {
  it("fills missing number shortcuts without replacing the saved URL binding", () => {
    const olderServerBindings = DEFAULT_RESOLVED_KEYBINDINGS.filter(
      (binding) =>
        binding.command !== "pullRequest.copyNumber" && binding.command !== "thread.copyReference",
    );
    const bindings = mergeWithDefaultKeybindings([
      ...olderServerBindings,
      ...compileResolvedKeybindingsConfig([
        { key: "mod+shift+8", command: "thread.copyReference", when: "!terminalFocus" },
      ]),
    ]);
    for (const [key, command] of [
      ["k", "pullRequest.copyNumber"],
      ["8", "thread.copyReference"],
      ["c", null],
      ["y", null],
    ] as const) {
      assert.strictEqual(
        resolveShortcutCommand(event({ key, metaKey: true, shiftKey: true }), bindings, {
          platform: "MacIntel",
        }),
        command,
      );
    }
  });

  it.each(["terminalOpen", "previewFocus", "previewOpen", "modelPickerOpen"])(
    "honors custom PR shortcut conditions for %s",
    (condition) => {
      const bindings = compileResolvedKeybindingsConfig([
        { key: "mod+shift+k", command: "thread.copyReference", when: condition },
        { key: "mod+shift+k", command: "pullRequest.copyNumber", when: `!${condition}` },
      ]);
      const input = event({ key: "k", ctrlKey: true, shiftKey: true });
      for (const enabled of [false, true]) {
        assert.strictEqual(
          resolveShortcutCommand(input, bindings, {
            platform: "Linux",
            context: { [condition]: enabled },
          }),
          enabled ? "thread.copyReference" : "pullRequest.copyNumber",
        );
      }
    },
  );

  const shortcuts = [
    ["h", "composer.host"],
    ["e", "composer.effort"],
    ["a", "composer.mode"],
    ["x", "composer.workspace"],
    ["g", "composer.branch"],
    ["l", "composer.previousWorktree"],
    ["c", "thread.copyReference"],
    ["k", "pullRequest.copyNumber"],
    ["Enter", "thread.steerQueuedMessage"],
  ] as const;

  for (const platform of ["MacIntel", "Win32", "Linux"]) {
    it.each(shortcuts)(
      `resolves %s on ${platform} and leaves terminal input alone`,
      (key, command) => {
        const input = event({
          key,
          shiftKey: true,
          metaKey: platform === "MacIntel",
          ctrlKey: platform !== "MacIntel",
        });
        assert.strictEqual(
          resolveShortcutCommand(input, DEFAULT_RESOLVED_KEYBINDINGS, {
            platform,
            context: { terminalFocus: false },
          }),
          command,
        );
        assert.isNull(
          resolveShortcutCommand(input, DEFAULT_RESOLVED_KEYBINDINGS, {
            platform,
            context: { terminalFocus: true },
          }),
        );
      },
    );
  }

  for (const platform of ["MacIntel", "Win32", "Linux"]) {
    it.each([
      ["s", "thread.settle"],
      ["p", "thread.pin"],
    ])(`preserves the existing %s shortcut on ${platform}`, (key, command) => {
      assert.strictEqual(
        resolveShortcutCommand(
          event({
            key,
            shiftKey: true,
            metaKey: platform === "MacIntel",
            ctrlKey: platform !== "MacIntel",
          }),
          DEFAULT_RESOLVED_KEYBINDINGS,
          { platform },
        ),
        command,
      );
    });
  }

  const altEffortBindings = compileResolvedKeybindingsConfig([
    { key: "mod+alt+e", command: "composer.effort", when: "!terminalFocus" },
  ]);

  it("leaves AltGr text entry alone with a custom Alt binding", () => {
    for (const platform of ["Win32", "Linux"]) {
      const input = event({
        key: "€",
        code: "KeyE",
        ctrlKey: true,
        altKey: true,
        getModifierState: (key) => key === "AltGraph",
      });
      assert.isNull(resolveShortcutCommand(input, altEffortBindings, { platform }));
      assert.strictEqual(
        resolveShortcutCommand({ ...input, getModifierState: () => false }, altEffortBindings, {
          platform,
        }),
        "composer.effort",
      );
    }
  });

  it("keeps Firefox modifier reporting usable on Windows and macOS", () => {
    const getModifierState = (key: string) => key === "AltGraph";
    assert.strictEqual(
      resolveShortcutCommand(
        event({ key: "e", ctrlKey: true, altKey: true, getModifierState }),
        altEffortBindings,
        { platform: "Win32" },
      ),
      "composer.effort",
    );
    assert.strictEqual(
      resolveShortcutCommand(
        event({ key: "´", code: "KeyE", metaKey: true, altKey: true, getModifierState }),
        altEffortBindings,
        { platform: "MacIntel" },
      ),
      "composer.effort",
    );
  });

  it.each(shortcuts)("uses a custom binding for %s", (_key, command) => {
    const bindings = compileResolvedKeybindingsConfig([
      { key: "mod+shift+y", command, when: "!terminalFocus" },
    ]);
    assert.strictEqual(
      resolveShortcutCommand(
        event({ key: "Y", code: "KeyY", ctrlKey: true, shiftKey: true }),
        bindings,
        { platform: "Linux" },
      ),
      command,
    );
  });

  for (const platform of ["MacIntel", "Win32", "Linux"]) {
    it.each([
      ["ArrowUp", "modelPicker.previousProvider"],
      ["ArrowDown", "modelPicker.nextProvider"],
    ] as const)(`limits %s to the model picker on ${platform}`, (key, command) => {
      const input = event({
        key,
        shiftKey: true,
        metaKey: platform === "MacIntel",
        ctrlKey: platform !== "MacIntel",
      });
      assert.strictEqual(
        resolveShortcutCommand(input, DEFAULT_RESOLVED_KEYBINDINGS, {
          platform,
          context: { modelPickerOpen: true },
        }),
        command,
      );
      assert.isNull(
        resolveShortcutCommand(input, DEFAULT_RESOLVED_KEYBINDINGS, {
          platform,
          context: { modelPickerOpen: false },
        }),
      );
    });
  }
});

import { Outlet, createFileRoute, redirect } from "@tanstack/react-router";
import { scopedThreadKey, scopeThreadRef } from "@t3tools/client-runtime/environment";
import { useAtomValue } from "@effect/atom-react";
import { useEffect, useMemo } from "react";

import { isCommandPaletteOpen } from "../commandPaletteBus";
import { useClientSettings, useLegacySidebarEnabled } from "../hooks/useSettings";
import { openCommandPalette } from "../commandPaletteBus";
import { useProjects } from "../state/entities";
import { usePrimaryEnvironmentId } from "../state/environments";
import { selectProjectGroupingSettings } from "../logicalProject";
import { buildSidebarProjectSnapshots } from "../sidebarProjectGrouping";
import { dispatchPreviewAction } from "../components/preview/previewActionBus";
import { useHandleNewThread } from "../hooks/useHandleNewThread";
import { startNewThreadFromContext } from "../lib/chatThreadActions";
import { isPreviewFocused } from "../lib/previewFocus";
import { isTerminalFocused } from "../lib/terminalFocus";
import { resolveShortcutCommand } from "../keybindings";
import { openSessionSearch } from "../sessionSearchBus";
import { selectThreadTerminalUiState, useTerminalUiStateStore } from "../terminalUiStateStore";
import { isPreviewSupportedInRuntime } from "../previewStateStore";
import { selectActiveRightPanel, useRightPanelStore } from "../rightPanelStore";
import { useThreadSelectionStore } from "../threadSelectionStore";
import { stackedThreadToast, toastManager } from "~/components/ui/toast";
import { primaryServerKeybindingsAtom } from "~/state/server";

function ChatRouteGlobalShortcuts() {
  const clearSelection = useThreadSelectionStore((state) => state.clearSelection);
  const selectedThreadKeysSize = useThreadSelectionStore((state) => state.selectedThreadKeys.size);
  const { activeDraftThread, activeThread, defaultProjectRef, handleNewThread, routeThreadRef } =
    useHandleNewThread();
  const keybindings = useAtomValue(primaryServerKeybindingsAtom);
  const legacySidebarEnabled = useLegacySidebarEnabled();
  const projectGroupingSettings = useClientSettings(selectProjectGroupingSettings);
  const projects = useProjects();
  const primaryEnvironmentId = usePrimaryEnvironmentId();
  const projectGroupCount = useMemo(
    () =>
      buildSidebarProjectSnapshots({
        projects,
        settings: projectGroupingSettings,
        primaryEnvironmentId,
        resolveEnvironmentLabel: () => null,
      }).length,
    [primaryEnvironmentId, projectGroupingSettings, projects],
  );
  const terminalOpen = useTerminalUiStateStore((state) =>
    routeThreadRef
      ? selectThreadTerminalUiState(state.terminalUiStateByThreadKey, routeThreadRef).terminalOpen
      : false,
  );
  // The `previewOpen` shortcut-context flag here uses the store-only value;
  // the URL-aware arbitration lives inside ChatView's `onTogglePreview`,
  // which we invoke via the action bus to avoid duplicating the rule.
  const previewOpen = useRightPanelStore((state) =>
    routeThreadRef
      ? selectActiveRightPanel(state.byThreadKey, routeThreadRef) === "preview"
      : false,
  );
  useEffect(() => {
    const onWindowKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented) return;
      const command = resolveShortcutCommand(event, keybindings, {
        context: {
          terminalFocus: isTerminalFocused(),
          terminalOpen,
          previewFocus: isPreviewFocused(),
          previewOpen,
        },
      });

      if (isCommandPaletteOpen()) {
        return;
      }

      if (event.key === "Escape" && selectedThreadKeysSize > 0) {
        event.preventDefault();
        clearSelection();
        return;
      }

      if (command === "chat.search") {
        if (activeThread === null && activeDraftThread === null) {
          return;
        }
        const threadKey = activeThread
          ? scopedThreadKey(scopeThreadRef(activeThread.environmentId, activeThread.id))
          : activeDraftThread
            ? scopedThreadKey(
                scopeThreadRef(activeDraftThread.environmentId, activeDraftThread.threadId),
              )
            : null;
        if (threadKey && openSessionSearch(threadKey)) {
          event.preventDefault();
          event.stopPropagation();
        }
        return;
      }

      if (command === "chat.newLocal") {
        event.preventDefault();
        event.stopPropagation();
        void startNewThreadFromContext({
          activeDraftThread,
          activeThread: activeThread ?? undefined,
          defaultProjectRef,
          handleNewThread,
        });
        return;
      }

      if (command === "chat.new") {
        event.preventDefault();
        event.stopPropagation();
        // The default sidebar routes creation through the command palette
        // whenever there is a real choice to make; the legacy sidebar (and
        // single-project setups) keep the immediate contextual create.
        if (!legacySidebarEnabled && projectGroupCount > 1) {
          openCommandPalette({ open: "new-thread-in" });
          return;
        }
        void startNewThreadFromContext({
          activeDraftThread,
          activeThread: activeThread ?? undefined,
          defaultProjectRef,
          handleNewThread,
        });
        return;
      }

      if (command === "preview.toggle") {
        event.preventDefault();
        event.stopPropagation();
        if (!routeThreadRef) return;
        if (!isPreviewSupportedInRuntime()) {
          toastManager.add(
            stackedThreadToast({
              type: "info",
              title: "Preview is desktop-only",
              description: "Open T3 Code in the desktop app to use the in-app preview.",
            }),
          );
          return;
        }
        dispatchPreviewAction("toggle-panel");
        return;
      }

      // The remaining preview commands only fire when the panel is the
      // currently-focused tenant. The `when: previewFocus` rule already
      // gates this, but defend against the keybinding being misconfigured.
      if (
        command === "preview.refresh" ||
        command === "preview.focusUrl" ||
        command === "preview.zoomIn" ||
        command === "preview.zoomOut" ||
        command === "preview.resetZoom"
      ) {
        event.preventDefault();
        event.stopPropagation();
        const action =
          command === "preview.refresh"
            ? "refresh"
            : command === "preview.focusUrl"
              ? "focus-url"
              : command === "preview.zoomIn"
                ? "zoom-in"
                : command === "preview.zoomOut"
                  ? "zoom-out"
                  : "reset-zoom";
        dispatchPreviewAction(action);
      }
    };

    window.addEventListener("keydown", onWindowKeyDown);
    return () => {
      window.removeEventListener("keydown", onWindowKeyDown);
    };
  }, [
    activeDraftThread,
    activeThread,
    clearSelection,
    handleNewThread,
    keybindings,
    defaultProjectRef,
    previewOpen,
    projectGroupCount,
    routeThreadRef,
    selectedThreadKeysSize,
    legacySidebarEnabled,
    terminalOpen,
  ]);

  return null;
}

function ChatRouteLayout() {
  return (
    <>
      <ChatRouteGlobalShortcuts />
      <Outlet />
    </>
  );
}

export const Route = createFileRoute("/_chat")({
  beforeLoad: async ({ context }) => {
    if (
      context.authGateState.status !== "authenticated" &&
      context.authGateState.status !== "hosted-static"
    ) {
      throw redirect({ to: "/pair", replace: true });
    }
  },
  component: ChatRouteLayout,
});

const SESSION_SEARCH_OPEN_EVENT = "t3code:open-session-search";

export function openSessionSearch(threadKey: string): boolean {
  const event = new CustomEvent(SESSION_SEARCH_OPEN_EVENT, { detail: threadKey, cancelable: true });
  window.dispatchEvent(event);
  return event.defaultPrevented;
}

export function onOpenSessionSearch(listener: (threadKey: string) => boolean): () => void {
  const handler = (event: Event) => {
    if (
      event instanceof CustomEvent &&
      typeof event.detail === "string" &&
      listener(event.detail)
    ) {
      event.preventDefault();
    }
  };
  window.addEventListener(SESSION_SEARCH_OPEN_EVENT, handler);
  return () => window.removeEventListener(SESSION_SEARCH_OPEN_EVENT, handler);
}

import { assert, it } from "@effect/vitest";
